const SUM: Record<string, any> = {"28.10.2026": {"g": [["Аэрофлот", "М. Мишустин встретился с гендиректором «Аэрофлота» С. Александровским: итоги 9 месяцев, рост внутренних и международных перевозок, поставки новых отечественных самолетов, замена импортных систем техобслуживания и ремонта.", "60297"], ["Совет Федерации", "Д. Мантуров на правительственном часе в СФ: с 2022 года обрабатывающее производство выросло более чем на 20%; средняя зарплата в отрасли +11% за год, до 109 тыс. руб.; на нацпроекты технологического лидерства уже направлено 600 млрд руб., в проекте бюджета на три года — еще около 2 трлн; на докапитализацию ФРП заложено 205 млрд руб.", "60300"], ["Ядерная медицина", "Т. Голикова провела первое заседание межведомственной рабочей группы по ядерной медицине (создана по поручению Президента, сопровождает Курчатовский институт); 93% зарегистрированных радиофармпрепаратов производится в России.", "60299"], ["Животноводство", "Д. Патрушев провел заседание правительственной противоэпизоотической комиссии: вакцинация поголовья — ключевой инструмент ветеринарной безопасности; экспорт мясо-молочной продукции — более чем в 100 стран.", "60301"], ["Россия – Африка", "А. Новак принял участие в подписании меморандума между «ВЭБ.РФ» и Конфедеративным банком инвестиций и развития государств Сахеля (Нигер, Мали, Буркина-Фасо).", "60298"], ["Мурманская область", "О. Кожемяко встретился с губернатором А. Чибисом: подготовка Международного арктического форума (март 2027 года), комплексный проект развития Арктической зоны и Трансарктического коридора, бюджет региона.", "60304"], ["Красноярский край", "М. Хуснуллин встретился с губернатором М. Котюковым и осмотрел стройку линии скоростного легкорельсового транспорта в Красноярске; 75% дорог в нормативном состоянии, с 2020 года поставлено более 400 единиц общественного транспорта.", "60306"]]}, "30.09.2026": {"g": [["Бюджет", "Внесен в Госдуму проект федерального бюджета на 2027–2029 годы вместе с бюджетами внебюджетных фондов (распоряжение от 30.09.2026 №2706-р).", "60046"], ["Постановление", "Механизм повышенного авансирования закупок промышленной продукции (не менее 80% цены контракта) продлен до 2030 года, перечень расширен на 22 позиции (постановление от 26.09.2026 №1243).", "60030"], ["Постановление", "Продлен временный запрет на вывоз отдельных видов топлива производителями (постановление от 29.09.2026 №1252); сроки в анонсе — подробности не раскрыты.", "60024"], ["Заседание кабинета", "Повестка: авансирование закупок промпродукции, возмещение регионам затрат на тушение лесных пожаров, ассигнования на проект «Формирование комфортной городской среды».", "60029"]]}, "01.10.2026": {"g": [["Союзное государство", "Заседание Совета Министров Союзного государства (Мишустин, Турчин); подписан ряд документов — перечень подробно не раскрыт.", "60050"], ["Вступил в силу закон", "С 1 октября действует закон «О платформенной экономике»: единые правила работы маркетплейсов и крупных цифровых сервисов (заявление Д. Григоренко).", "60052"], ["Решения заседания", "Опубликованы решения заседания 30.09.2026, в т.ч. одобрен законопроект об изменениях в «Основы законодательства о культуре» (госуслуги в сфере культуры через информсистему Минкультуры).", "60044"]]}, "13.10.2026": {"g": [["Постановление", "С 2027 года аграрии ДНР, ЛНР, Запорожской и Херсонской областей получат субсидии на часть страховой премии по агрострахованию (постановление от 09.10.2026 №1326).", "60163"], ["Распоряжение", "Более 1,2 млрд руб. Удмуртии, Красноярскому краю и Свердловской области на строительство школ и детсадов (распоряжение от 09.10.2026 №2850-р).", "60162"], ["Оперативное совещание", "Повестка: школы и детсады, агрострахование в новых регионах, Стратегия развития спортивной медицины до 2030 года.", "60161"], ["Заявление", "М. Хуснуллин: с 2021 года ИБК, СКК и КИК привлекли на Северный Кавказ почти 130 млрд руб. внебюджетных инвестиций.", "60171"]]}, "14.10.2026": {"g": [["Заявление", "Ю. Трутнев: определены даты Восточного экономического форума 2027 года; даты — см. источник, подробности в анонсе не раскрыты.", "60176"], ["Решение оргкомитета", "Т. Голикова: утвержден перечень номинаций конкурса «Лучший по профессии» на 2027 год — 25 номинаций.", "60181"]]}, "15.10.2026": {"g": [["Распоряжения", "Свыше 1,6 млрд руб. Калининградской и Нижегородской областям на экологичный общественный транспорт (распоряжения от 15.10.2026 №2916-р, №2921-р).", "60195"], ["Распоряжение", "Расширен перечень стратегически значимых лекарственных средств (распоряжение от 13.10.2026 №2895-р); число позиций — подробности не раскрыты.", "60194"], ["Заседание кабинета", "Повестка: перечень стратегически значимых лекарств, бюджетные ассигнования и другие вопросы; подробности не раскрыты.", "60193"]]}, "20.10.2026": {"g": [["ШОС", "Заседание Совета глав правительств ШОС в узком составе с участием М. Мишустина; итоговые решения — подробности не раскрыты.", "60229"], ["ШОС", "Заседание Совета глав правительств ШОС в расширенном составе.", "60230"]]}, "21.10.2026": {"g": [["Россия–Китай", "Совместное коммюнике по итогам 31-й регулярной встречи глав правительств России и Китая (визит Ли Цяна 20–21.10.2026).", "60255"], ["ШОС", "Совместное коммюнике по итогам 25-го заседания Совета глав правительств ШОС.", "60248"], ["Генпланы", "М. Хуснуллин: утверждены генпланы пяти муниципальных округов Херсонской области.", "60259"]]}, "22.10.2026": {"g": [["Назначения", "Заседание правительства: о новых назначениях в правительстве и госнаградах Д. Григоренко, В. Савельеву и др.; состав назначений — см. источник.", "60265"], ["Указ", "Президент подписал указ об изменении структуры федеральных органов исполнительной власти; подробности не раскрыты.", "60264"]]}, "27.10.2026": {"g": [["Стратегическая сессия", "М. Мишустин — о трех нацпроектах технологического лидерства (продовольственная безопасность, транспортная мобильность, беспилотные системы): цифровая платформа селекции сокращает сроки выведения сортов примерно втрое — до 2–3 лет; на Севморпуть вышел второй серийный арктический танкер-газовоз верфи «Звезда»; изготовлены кузовы вагонов для трех высокоскоростных электропоездов; Ил-114 и двигатель ПД-8 подтвердили соответствие требованиям; комплектующих БАС в реестре за 9 месяцев +почти 80%.", "60290"], ["Нацпроект «Кадры»", "Т. Голикова, итоги 9 месяцев: создано 59 кадровых центров «Работа России», время трудоустройства в модернизированных центрах −33%; модернизировано 162 центра карьеры вузов; независимую оценку квалификаций прошли более 86 тыс. человек; бесплатное обучение завершили 75 тыс., учатся почти 40 тыс.; ветеранам СВО доступно обучение по 213 профессиям; субсидия до 200 тыс. руб. на оборудование рабочих мест для людей с инвалидностью — свыше 1,5 тыс. мест.", "60294"], ["Кузбасс", "М. Хуснуллин в Кемерове: под КРТ 34 территории, реализуется 22 проекта; первый дом по КРТ (240 квартир, все проданы) — ввод до конца 2026 года; под комплексную застройку 540 га — 23 микрорайона, 3,4 млн кв. м жилья, около 120 тыс. жителей; музейно-театральный комплекс готов более чем на 70%, ввод в 2027 году; доля нормативных дорог опорной сети — 84,5%.", "60293"], ["Алтайский край", "М. Хуснуллин: с начала года введено около 756 тыс. кв. м жилья (+9,5%); 66 опорных населенных пунктов (почти 70% населения); 6 площадок КРТ на 1391 га, 5 проектов; опорная сеть 3121 км, в нормативе 70,64%; в 2026 году — 62 автобуса; 11 проектов с ИБК; казначейские кредиты на ЖКХ — свыше 4,4 млрд руб.", "60295"], ["Удмуртия", "Д. Патрушев и врио главы О. Абрамова: намолочено более 650 тыс. т зерна (цель — 1 млн т), озимые — более 50 тыс. га; молоко — более 900 тыс. т за 9 месяцев (4-е место в стране); 30 объектов по программе развития сельских территорий; 5 мусоросортировочных комплексов на 395 тыс. т в год; лесовосстановление — 10,6 тыс. га.", "60291"], ["Совет Федерации", "Д. Мантуров на заседании комитета СФ по экономической политике: поддержка экономики при напряженной денежно-кредитной политике, адресные меры для реального сектора; обсуждены легкая промышленность и металлургия. Конкретные решения: подробности не раскрыты.", "60292"], ["Мозамбик", "Д. Мантуров встретился с президентом Мозамбика Д. Чапо перед форумом «Россия – Африка»; подписаны меморандум с уполномоченным по правам человека в РФ и соглашение с АНО «Евразия» (образование, наука, молодежные обмены).", "60289"]]}, "29.10.2026": {"g": [["Заседание Правительства", "М. Мишустин: подготовка ЖКХ и энергетики к зиме — в рамках проекта «Модернизация коммунальной инфраструктуры» в этом году построено и отремонтировано около 250 объектов (котельные, насосные станции, сети), сформированы резервы топлива сверх нормативов; аграриям выделено свыше 720 млн руб. на возмещение расходов по льготным кредитам (185 кредитов); одобрен законопроект о подготовительных работах на промышленных площадках до получения разрешения на строительство.", "60309"], ["Технологическая политика", "М. Мишустин утвердил поручения по итогам стратсессии о технологической политике (8 сентября): создать Совет главных конструкторов (предложения — до 31.05.2027), актуализировать карты технологической кооперации с механизмами гарантированного спроса (до 01.03.2027), закрепить сквозные и критические технологии за ведомствами (до 31.03.2027).", "60305"], ["Kazan Digital Week", "Видеообращение М. Мишустина к форуму: доля ИТ-отрасли в ВВП за шесть лет выросла более чем вдвое, в реестре отечественного ПО — десятки тысяч решений.", "60307"], ["Металлургия", "Д. Мантуров провел заседание подкомиссии по бесперебойному функционированию отраслей экономики: устойчивость металлургического комплекса, физическая защищенность предприятий, сокращение сроков ремонтов, запасы критических комплектующих.", "60314"], ["Старшее поколение", "Т. Голикова провела заседание Совета по попечительству в социальной сфере: 18% граждан старше 65 лет (с предпенсионерами — около 24%), 3 млн пенсионеров продолжают работать; по программе переобучения граждан старше 50 лет нацпроекта «Кадры» в прошлом году обучились 23,5 тыс. человек.", "60313"], ["Соловки", "Д. Чернышенко провел совещание о сохранении и развитии Соловецкого архипелага к 600-летию первого монашеского поселения (2029 год): сроки реставрации и строительства объектов.", "60312"], ["Россия – Танзания", "А. Новак на саммите «Россия – Африка» встретился с премьер-министром Танзании М. Нчембой: ТЭК, геологоразведка и добыча урана, промышленность, транспорт, финансы.", "60310"], ["Дороги", "М. Хуснуллин: по нацпроекту «Инфраструктура для жизни» с начала года на региональных и местных дорогах установлено 150 тыс. пог. м освещения, 396,8 тыс. пог. м барьерных и 73,1 тыс. пог. м пешеходных ограждений, обустроено 446,1 тыс. пог. м тротуаров, более 68,7 тыс. знаков.", "60311"], ["Кампус МГСУ", "М. Хуснуллин: строительная готовность кампуса НИУ МГСУ — 75%, блоки «А» и «Б» (около 70 тыс. кв. м) планируется ввести в 2027 году.", "60308"]]},"30.10.2026":{"g":[["Распределение обязанностей","М. Мишустин утвердил распределение обязанностей между вице-премьерами обновлённого кабинета: Д. Мантуров — нацпроекты «Средства производства и автоматизация», «Новые материалы и химия», «Промышленное обеспечение транспортной мобильности», космос до 2030/2036, биоэкономика; Т. Голикова — «Продолжительная и активная жизнь», «Семья», «Кадры», «Новые технологии сбережения здоровья»; О. Кожемяко — Дальний Восток и Арктика, Минвостокразвития; А. Никитин — транспорт, нацпроекты «Беспилотные авиационные системы» и «Эффективная транспортная система», Минтранс и Росавиация; А. Новак — дополнительно платформенная экономика и производительность труда, нацпроекты «Эффективная и конкурентная экономика», «Новые атомные и энергетические технологии».","60323"],["Росавиация","М. Мишустин назначил Н. Андрианову врио руководителя Росавиации (ранее — заместитель руководителя с 2021 года).","60325"],["Кампусы","Отобраны 19 новых проектов современных университетских кампусов в 17 городах (4-й отбор Минобрнауки): площадь около 2 млн кв. м, 29 тыс. мест проживания, финансирование 474 млрд руб. (224 млрд из федерального бюджета). В работе — 25 проектов в 23 регионах (896,93 млрд руб.); введено 41 объект из 123.","60316"],["Кампус НГУ","М. Хуснуллин: на базе кампуса НГУ завершено строительство научно-исследовательского центра (медицина, химия, биология, около 180 сотрудников); ввод — до конца 2026 года. Общая площадь кампуса — около 78 тыс. кв. м.","60330"],["Автобусы","М. Хуснуллин: ещё 40 новых автобусов отечественного производства переданы восьми регионам (льготный лизинг Минпромторга и нацпроект «Инфраструктура для жизни»): Московская область — 22, Челябинская — 7, Липецкая — 3, Красноярский край — 3, Пермский край — 2 и др.","60321"],["Курская область","М. Хуснуллин встретился с губернатором А. Хинштейном: с начала года введено более 480 тыс. кв. м жилья, почти 90% опорной дорожной сети в нормативном состоянии; в 2026 году поставлено 22 новых автобуса; КРТ — 11 площадок (446,7 га).","60331"],["Псковская область","Д. Мантуров посетил предприятия «Акрон Холдинга» («Севкабель», «СКТ-сервис») и завод «АВАР»; встретился с губернатором М. Ведерниковым. Индекс промпроизводства региона за 8 месяцев 2026 — 102,1%; ФРП с 2016 года — более 10 млрд руб. на 13 проектов.","60322"],["РТК","Т. Голикова провела заседание Российской трёхсторонней комиссии: поддержан проект поправок в ТК о профессионально-квалификационных характеристиках; рассмотрены итоги конкурса «Российская организация высокой социальной эффективности» (1424 организации, 53 победителя и призёра).","60320"],["Ответственный бизнес","Т. Голикова и А. Шохин объявили старт 4-го цикла национальной премии «Лидеры ответственного бизнеса»; заявки — до 10.12.2026. В 2025 году — 101 заявка (вдвое больше), 66 прошли предквалификацию.","60333"],["День тренера","Д. Чернышенко и М. Дегтярёв поздравили тренеров: в системе подготовки спортивного резерва — около 88 тыс. тренеров; программа «Земский тренер» — 2,73 млрд руб. до 2028 года, выплаты 1–2 млн руб. в 86 субъектах.","60319"],["За верность науке","Д. Чернышенко, В. Фальков и Г. Красников наградили лауреатов XII Всероссийской премии «За верность науке» (более 2 тыс. заявок, 11 номинаций).","60336"],["Герой России","О. Кожемяко передал семье гвардии подполковника Н. Шихалиева медаль «Золотая звезда» (звание Героя РФ посмертно).","60334"],["Решения заседания 29.10","Опубликованы решения заседания Правительства от 29.10: контроль прохождения ОЗП 2026–2027; одобрены законопроекты (ст. 28.3 и 15.47 КоАП — драгметаллы; ст. 52 ГрК — подготовительные работы; ст. 51 закона о защите конкуренции и др.).","60318"]]}};
