let GZ = 1;
const revealCard = (id: string, again = true) => {
  if (again) setTimeout(() => revealCard(id, false), 160);
  const wr = document.querySelector(`[data-vid="${id}"]`) as HTMLElement | null; const row = wr && wr.firstElementChild as HTMLElement | null; if (!wr || !row) return;
  let bx = wr.parentElement; while (bx && bx !== document.body) { const o = getComputedStyle(bx).overflowY; if ((o === 'auto' || o === 'scroll') && bx.scrollHeight > bx.clientHeight) break; bx = bx.parentElement; }
  const bar = document.querySelector('[data-gdbar]') as HTMLElement | null; const barB = () => { if (!bar) return 0; const r = bar.getBoundingClientRect(); return r.top <= 1 && r.height > 0 ? r.bottom : 0; };
  if (bx && bx !== document.body) { const d = bx.getBoundingClientRect().top - barB(); if (d < 0) window.scrollBy(0, d); const hd = bx.querySelector('[data-colhead]') as HTMLElement | null; bx.scrollTop += (wr.getBoundingClientRect().top - Math.max(bx.getBoundingClientRect().top, barB())) / GZ - (hd ? hd.offsetHeight : 0); }
  else { const tp = Math.max(barB(), parseFloat(getComputedStyle(document.documentElement).getPropertyValue('--gd-top')) || 0); window.scrollBy(0, wr.getBoundingClientRect().top - tp); }
};
const iniMixed = (s: string): any => { const rows: any[] = []; s.split(/;\s*/).forEach((seg, k) => { const mm = seg.match(/^(Депутаты Государственной Думы|Депутат Государственной Думы|Сенаторы Российской Федерации|Сенатор Российской Федерации)[\s,:]*/); const body = mm ? seg.slice(mm[0].length) : seg; if (mm && /^Депутат/.test(mm[1])) { const w = withParty(body); rows.push(<span key={k}>{w}</span>); } else rows.push(<span key={k}>{mm && <b style={{ color: (DK ? '#409CFF' : 'rgb(10,100,214)') }}>{mm[1].replace(' Российской Федерации', '')}: </b>}{body}</span>); }); return <span style={{ display: 'flex', flexDirection: 'column', gap: 2 }}>{rows}</span>; };
const withParty = (s?: string, cv?: string): any => { if (!s) return s; const re = /((?:[А-ЯЁ]\.\s?){1,2})([А-ЯЁ][а-яё]+(?:-[А-ЯЁ][а-яё]+)?)/g; const g: Record<string, string[]> = {}; let first = -1, hit = false, mm: RegExpExecArray | null; while ((mm = re.exec(s))) { if (first < 0) first = mm.index; const io = mm[1].replace(/\s/g, ''); const nk = (mm[2] + ' ' + io).replace(/ё/g, 'е'); const p = cv === '7' ? DEP7[nk] || DEP[nk] : DEP[nk] || DEP8[nk]; if (p) hit = true; (g[p || ''] = g[p || ''] || []).push(io + ' ' + mm[2]); } if (!hit) return s; const pre = s.slice(0, first).replace(/[\s,:]+$/, ''); return <span style={{ display: 'flex', flexDirection: 'column', gap: 2 }}>{pre && <span>{pre}</span>}{Object.entries(g).map(([p, l]) => <span key={p}>{p && <b style={{ color: (DK ? '#409CFF' : 'rgb(10,100,214)') }}>{p}: </b>}{l.join(', ')}</span>)}</span>; };
