    for (const k of ['ЕР', 'КПРФ', 'ЛДПР', 'НЛ', 'СРЗП']) { const f = (v.fr as any)?.[k]; if (!f || !f.size) continue; const [z, p, , n] = f.v; if (z > f.size / 2) gs.za.push(FFULL[k]); else if (n >= f.size / 2) gs.ng.push(FFULL[k]); else if (p > f.size / 2) gs.pr.push(FFULL[k]); }
