const GOVA: Record<string, [string, string][]> = { '09.09.2026': [["О проекте федерального закона «О внесении изменений в статью 78.3 Бюджетного кодекса Российской Федерации»", "Законопроект направлен на распространение на субсидии, предоставляемые из федерального бюджета государственным корпорациям (компаниям) и публично-правовым компаниям, требований, аналогичных общим требованиям к порядкам предоставления субсидий юридическим лицам."], ["О выделении Минфину России в 2026 году из резервного фонда Правительства Российской Федерации бюджетных ассигнований", "Проектом распоряжения предлагается предоставить бюджету Республики Крым дотации на поддержку мер по обеспечению сбалансированности бюджетов субъектов Российской Федерации."], ["О выделении Минфину России в 2026 году из резервного фонда Правительства Российской Федерации бюджетных ассигнований", "Проект распоряжения направлен на предоставление бюджетам Республики Алтай, Чеченской Республики, Рязанской области и Тверской области дотаций на поддержку мер по обеспечению сбалансированности бюджетов субъектов Российской Федерации."], ["О проекте федерального закона «О внесении изменений в статьи 2 и 5 Закона Российской Федерации “О праве граждан Российской Федерации на свободу передвижения, выбор места пребывания и жительства в пределах Российской Федерации„»", "Законопроект направлен на приведение используемой в Законе Российской Федерации от 25 июня 1993 года №5242-1 «О праве граждан Российской Федерации на свободу передвижения, выбор места пребывания и жительства в пределах Российской Федерации» терминологии в отношении средств размещения в соответствие с нормами Федерального закона от 24 ноября 1996 года №132-ФЗ «Об основах туристской деятельности в Российской Федерации»."], ["О проекте федерального закона «О внесении изменений в Федеральный закон “О геодезии, картографии и пространственных данных и о внесении изменений в отдельные законодательные акты Российской Федерации„»", "Законопроект направлен на совершенствование законодательства в сфере геодезии, картографии и пространственных данных."], ["О внесении изменений в постановление Правительства Российской Федерации от 19 июня 2012 года №607 (в части внесения изменений в Положение о Министерстве спорта Российской Федерации)", "Проект постановления направлен на актуализацию полномочий Минспорта России в части предотвращения допинга в спорте и борьбы с ним."], ["О проекте федерального закона «О внесении изменения в статью 234 части первой Гражданского кодекса Российской Федерации»", "Законопроект направлен на устранение неопределенности нормативного содержания пункта 3 статьи 234 Гражданского кодекса."]], '17.09.2026': [["О проекте федерального закона «О внесении изменений в статью 16 Федерального закона “О Следственном комитете Российской Федерации„»", "Законопроект направлен на обеспечение единого подхода к решению кадровых вопросов в системе Следственного комитета и совершенствования порядка поступления на службу в следственные органы и учреждения Следственного комитета."], ["О проекте федерального закона «О внесении изменений в Федеральный закон “Об исполнительном производстве„»", "Законопроект разработан в связи с необходимостью сбалансированного регулирования прав и законных интересов всех участников исполнительного производства."], ["О проекте федерального закона «О внесении изменений в Закон Российской Федерации “О недрах„ и статью 20 Федерального закона “О драгоценных металлах и драгоценных камнях„»", "Законопроект направлен на совершенствование регулирования пользования участками недр, содержащими драгоценные металлы, а также порядка аффинажа драгоценных металлов в целях недопущения их незаконной добычи и оборота."], ["О выделении Минфину России в 2026 году из резервного фонда Правительства Российской Федерации бюджетных ассигнований", "Проект распоряжения направлен на предоставление публичному акционерному обществу «ДОМ.РФ» субсидий в виде вкладов в имущество, не увеличивающих его уставный капитал, на цели возмещения кредитным и иным организациям недополученных доходов по жилищным (ипотечным) кредитам (займам), выданным гражданам Российской Федерации."], ["О проекте федерального закона «О внесении изменения в статью 8 Федерального закона “О социальных гарантиях сотрудникам некоторых федеральных органов исполнительной власти и внесении изменений в отдельные законодательные акты Российской Федерации„»", "Законопроект направлен на совершенствование правового регулирования вопросов обеспечения жилыми помещениями из специализированного жилищного фонда."], ["О проекте федерального закона «О внесении изменений в статьи 284 и 427 части второй Налогового кодекса Российской Федерации»", "Законопроект направлен на поддержку российских организаций, осуществляющих производство и реализацию произведенной ими анимационной аудиовизуальной продукции."], ["О проекте федерального закона «О внесении изменений в Федеральный закон “Об автомобильных дорогах и о дорожной деятельности в Российской Федерации и о внесении изменений в отдельные законодательные акты Российской Федерации„ и Федеральный закон “О Государственной компании «Российские автомобильные дороги» и о внесении изменений в отдельные законодательные акты Российской Федерации„»", "Законопроект направлен на совершенствование норм, регламентирующих размещение объектов дорожного сервиса (включая мобильные объекты) вдоль автомобильных дорог, в том числе в составе многофункциональных зон дорожного сервиса."], ["О внесении изменений в распоряжение Правительства Российской Федерации от 22 января 2026 года №62-р", "Проект распоряжения направлен на увеличение Минстрою России в 2026 году объема бюджетных ассигнований за счет перераспределения средств, зарезервированных в федеральном бюджете, на предоставление дотаций на поддержку мер по обеспечению сбалансированности бюджетов Донецкой Народной Республики, Луганской Народной Республики, Запорожской и Херсонской областей в целях пенсионного обеспечения граждан."]], '24.09.2026': [["О прогнозе социально-экономического развития Российской Федерации на 2027 год и на плановый период 2028 и 2029 годов", "Доклад представлен Минэкономразвития России."], ["О проекте федерального закона «О федеральном бюджете на 2027 год и на плановый период 2028 и 2029 годов»", ""], ["О проекте федерального закона «О бюджете Фонда пенсионного и социального страхования Российской Федерации на 2027 год и на плановый период 2028 и 2029 годов»", ""], ["О внесении изменений в постановление Правительства Российской Федерации от 19 июня 2012 года №610 (в части внесения изменений в Положение о Министерстве труда и социальной защиты Российской Федерации)", "Проект постановления направлен на приведение положения в соответствие со статьей 4 Федерального закона от 29 декабря 2006 года №256-ФЗ «О дополнительных мерах государственной поддержки семей, имеющих детей» и пунктом 2 Правил разработки и утверждения административных регламентов предоставления государственных услуг, утвержденных постановлением Правительства Российской Федерации от 20 июля 2021 года №1228."], ["О проекте федерального закона «О бюджете Федерального фонда обязательного медицинского страхования на 2027 год и на плановый период 2028 и 2029 годов»", ""], ["О проекте федерального закона «О внесении изменений в статью 51 Федерального закона “Об обязательном медицинском страховании в Российской Федерации„»", ""], ["О проекте основных направлений единой государственной денежно-кредитной политики на 2027 год и период 2028 и 2029 годов", "В проекте документа содержатся цели и подходы проведения денежно-кредитной политики, текущее состояние экономики и прогнозы ее развития в среднесрочной перспективе."], ["О проекте федерального закона «О ратификации Соглашения между Правительством Российской Федерации и Правительством Китайской Народной Республики о совместном строительстве второго главного пути колеи 1435 мм на трансграничном участке железной дороги Забайкальск – Маньчжурия»", "Законопроектом предлагается ратифицировать соглашение, подписанное в Пекине 20 мая 2026 года."], ["О выделении Минпросвещения России в 2026 году из резервного фонда Правительства Российской Федерации бюджетных ассигнований на предоставление субсидии из федерального бюджета бюджету Тамбовской области", "Проект распоряжения направлен на софинансирование расходных обязательств для возмещения ранее произведенных расходов бюджета Тамбовской области с целью завершения строительства общеобразовательной школы на 1275 мест в Тамбове."]], '30.09.2026': [["О проекте федерального закона «О внесении изменений в Закон Российской Федерации “Основы законодательства Российской Федерации о культуре„ и Закон Российской Федерации “О вывозе и ввозе культурных ценностей„»", "Принятие законопроекта позволит обеспечить предоставление государственных услуг в сфере культуры посредством информационной системы и наделить Минкультуры России полномочиями по ее ведению."], ["О внесении изменений в постановление Правительства Российской Федерации от 5 июня 2008 года №438 (в части внесения изменений в Положение о Министерстве промышленности и торговли Российской Федерации)", "Проект постановления направлен на реализацию норм Федерального закона от 4 августа 2026 года №331-ФЗ «О внесении изменений в отдельные законодательные акты Российской Федерации»."], ["О выделении Рослесхозу в 2026 году из резервного фонда Правительства Российской Федерации бюджетных ассигнований на предоставление субвенций из федерального бюджета бюджетам субъектов Российской Федерации", "Проект распоряжения направлен на финансовое обеспечение затрат субъектов Российской Федерации на тушение лесных пожаров, а также мероприятий по мониторингу пожарной опасности в лесах и лесных пожаров с использованием авиационных средств."], ["О внесении изменений в распределения субсидий бюджетам субъектов Российской Федерации, утвержденные приложением 30 (таблицы 109, 110 и 141) к Федеральному закону «О федеральном бюджете на 2026 год и на плановый период 2027 и 2028 годов»", "Проект распоряжения направлен на обеспечение эффективности использования средств федерального бюджета, предусмотренных в 2026 году на реализацию мероприятий федерального проекта «Формирование комфортной городской среды» и федерального проекта «Модернизация коммунальной инфраструктуры»."]], '07.10.2026': [["О проекте федерального закона «О внесении изменений в Градостроительный кодекс Российской Федерации» (в части регулирования цифровой информационной модели)", "Законопроект подготовлен в целях повышения уровня цифровизации строительной отрасли, эффективности управления процессами строительства и эксплуатации объектов капитального строительства."], ["О внесении изменений в распределение субсидий бюджетам субъектов Российской Федерации, утвержденное приложением 30 (таблицы 100, 190 и 218) к Федеральному закону «О федеральном бюджете на 2026 год и на плановый период 2027 и 2028 годов»", "Проект распоряжения направлен на создание инженерной и транспортной инфраструктуры на территории субъектов Российской Федерации в целях развития туристических кластеров, осуществления строительства инженерной и транспортной инфраструктуры в целях создания федеральных круглогодичных курортов, а также завершение ранее начатых мероприятий по строительству (реконструкции) объектов обеспечивающей инфраструктуры с длительным сроком окупаемости в рамках федерального проекта «Создание номерного фонда, инфраструктуры и новых точек притяжения» национального проекта «Туризм и гостеприимство»."], ["О выделении Минстрою России в 2026 году из резервного фонда Правительства Российской Федерации бюджетных ассигнований для предоставления субсидии из федерального бюджета бюджету Республики Адыгея в целях софинансирования расходных обязательств по финансовому обеспечению создания инженерной и транспортной инфраструктуры для развития туристских кластеров", "Проект распоряжения направлен на финансовое обеспечение технологического присоединения к сетям газораспределения объектов всесезонного горного экокурорта «Лагонаки» в Республике Адыгея."], ["О проекте федерального закона «О внесении изменений в статью 13.1 Федерального закона “Об актах гражданского состояния„»", "Законопроект направлен на совершенствование механизма наполнения Единого государственного реестра записей актов гражданского состояния сведениями о документах, выданных компетентными органами иностранных государств в удостоверение актов гражданского состояния, совершенных вне пределов территории Российской Федерации по законам соответствующих иностранных государств."], ["О проекте федерального закона «О ратификации Протокола о внесении изменений в Договор между Российской Федерацией и Республикой Беларусь об общих принципах налогообложения по косвенным налогам от 3 октября 2022 года»", "Законопроект направлен на ратификацию протокола, подписанного 16 июля 2026 года в Москве."], ["О внесении изменений в постановление Правительства Российской Федерации от 19 июня 2012 года №608 (в части внесения изменений в Положение о Министерстве здравоохранения Российской Федерации)", "Проект постановления направлен на предотвращение распространения инфекционных заболеваний среди населения."], ["О внесении изменений в постановление Правительства Российской Федерации от 30 июня 2004 года №323 (в части внесения изменений в Положение о Федеральной службе по надзору в сфере здравоохранения)", "Проект постановления направлен на приведение полномочий Росздравнадзора в соответствие с нормами Федерального закона от 10 июня 2026 года №162-ФЗ «О внесении изменений в Федеральный закон “О правовом положении иностранных граждан в Российской Федерации„ и статью 34 Федерального закона “О санитарно-эпидемиологическом благополучии населения„»."], ["О проекте федерального закона «О внесении изменений в статьи 5 и 8 Федерального закона “Об особенностях пенсионного и дополнительного социального обеспечения граждан, проживающих на территориях Донецкой Народной Республики, Луганской Народной Республики, Запорожской области и Херсонской области„»", "Законопроект направлен на предоставление возможности гражданам, проживающим на территориях Донецкой Народной Республики, Луганской Народной Республики, Запорожской и Херсонской областей, обращаться в межведомственную комиссию по реализации трудовых, пенсионных и социальных прав отдельных категорий лиц для подтверждения периодов прохождения военной или иной приравненной к ней по пенсионному обеспечению службы в соответствии с нормативными правовыми актами, действовавшими на этих территориях Донецкой Народной Республики, Луганской Народной Республики, Запорожской и Херсонской областей Украины, в целях дальнейшего учета их в страховом стаже при назначении пенсии."], ["О проекте федерального закона «О внесении изменений в статью 25 Федерального закона “О безопасности дорожного движения„»", "Законопроект направлен на совершенствование порядка допуска к управлению транспортными средствами граждан Российской Федерации, постоянно проживающих в иностранном государстве."], ["О проекте федерального закона «О внесении изменения в статью 18 Закона Российской Федерации “О пенсионном обеспечении лиц, проходивших военную службу, службу в органах внутренних дел, Государственной противопожарной службе, органах по контролю за оборотом наркотических средств и психотропных веществ, учреждениях и органах уголовно-исполнительной системы, войсках национальной гвардии Российской Федерации, органах принудительного исполнения Российской Федерации, и их семей„»", "Законопроект направлен на обеспечение равных условий исчисления выслуги лет для назначения пенсий лицам, пенсионное обеспечение которых осуществляется в соответствии с Законом Российской Федерации от 12 февраля 1993 года №4468-I «О пенсионном обеспечении лиц, проходивших военную службу, службу в органах внутренних дел, Государственной противопожарной службе, органах по контролю за оборотом наркотических средств и психотропных веществ, учреждениях и органах уголовно-исполнительной системы, войсках национальной гвардии Российской Федерации, органах принудительного исполнения Российской Федерации, и их семей»."], ["О внесении изменения в распоряжение Правительства Российской Федерации от 6 мая 2026 года №1058-р", "Проект распоряжения направлен на выделение Росавиации в 2026 году из резервного фонда Правительства Российской Федерации дополнительных бюджетных ассигнований в целях предоставления субсидий из федерального бюджета российским аэропортам на частичное возмещение расходов по обычным видам деятельности и процентов по кредитным договорам или договорам займа в период введения режима временного ограничения полетов в аэропорты юга и центральной части России."]], '15.10.2026': [["О выделении Минпромторгу России в 2026 году из резервного фонда Правительства Российской Федерации бюджетных ассигнований на оказание разовой финансовой помощи в форме субсидии из федерального бюджета бюджету Нижегородской области", "Проект распоряжения направлен на софинансирование расходных обязательств, возникающих при предоставлении субсидий юридическим лицам на финансовое обеспечение части затрат на приобретение оборудования и техники при организации транспортного обслуживания населения с использованием экологического (наземного электрического) транспорта общего пользования."], ["О выделении Минпромторгу России в 2026 году из резервного фонда Правительства Российской Федерации бюджетных ассигнований на предоставление субсидий из федерального бюджета бюджетам субъектов Российской Федерации", "Проект распоряжения направлен на софинансирование расходных обязательств, возникающих при реализации региональных проектов при участии центров поддержки экспорта, а также в рамках региональных программ развития экспорта субъектов Российской Федерации."], ["О внесении изменений в постановление Правительства Российской Федерации от 12 июня 2008 года №450 (в части внесения изменений в Положение о Министерстве сельского хозяйства Российской Федерации)", "Проект постановления направлен на наделение Минсельхоза России полномочиями в целях реализации норм федеральных законов от 4 июля 2026 года №226-ФЗ «О внесении изменений в Федеральный закон “О государственном регулировании обеспечения плодородия земель сельскохозяйственного назначения„», от 4 августа 2026 года №320-ФЗ «О внесении изменений в Федеральный закон “О развитии сельского хозяйства„ и отдельные законодательные акты Российской Федерации„», от 4 августа 2026 года №330-ФЗ «О внесении изменений в отдельные законодательные акты Российской Федерации»."], ["О выделении Минсельхозу России в 2026 году из резервного фонда Правительства Российской Федерации бюджетных ассигнований на предоставление субсидий из федерального бюджета", "Проект распоряжения направлен на обслуживание текущих запасов федерального интервенционного фонда сельскохозяйственной продукции."], ["О проекте федерального закона «О ратификации Соглашения между Правительством Российской Федерации и Правительством Республики Беларусь об условиях деятельности Белорусско-Российского университета»", "Законопроект направлен на ратификацию соглашения, подписанного в городе Москве и городе Минске 30 января 2026 года."], ["О проекте федерального закона «О внесении изменения в статью 16 Федерального закона “Об индивидуальном (персонифицированном) учете в системах обязательного пенсионного страхования и обязательного социального страхования„»", "Принятие законопроекта направлено на создание технической возможности оперативного поступления на ЕЦП «Работа в России» сведений, необходимых для обеспечения мониторинга структуры рынка труда, движения рабочей силы, а также формирования прогноза потребности экономики Российской Федерации в кадрах."], ["О проекте федерального закона «О внесении изменений в Федеральный закон “Об обращении лекарственных средств„»", "Проект федерального закона направлен на развитие персонализированной медицины в Российской Федерации, а также регулирование обращения биологических лекарственных препаратов."], ["О выделении Минтрансу России в 2026 году из резервного фонда Правительства Российской Федерации бюджетных ассигнований на оказание разовой финансовой помощи в форме субсидии из федерального бюджета бюджету Калининградской области", "Проект распоряжения направлен на софинансирование расходных обязательств по финансовому обеспечению реализации мероприятий по замене подвижного состава общественного транспорта, находящегося не в нормативном состоянии."], ["О проекте федерального закона «О внесении изменений в Федеральный закон “О ведении гражданами садоводства и огородничества для собственных нужд и о внесении изменений в отдельные законодательные акты Российской Федерации„ и отдельные законодательные акты Российской Федерации»", "Законопроектом предлагается уточнить порядок возникновения права общей долевой собственности на имущество общего пользования садоводческого или огороднического некоммерческого товарищества с учетом положений Гражданского кодекса Российской Федерации, а также уточнить требования к включению земельных участков в границы территории ведения садоводства или огородничества для собственных нужд."]], '22.10.2026': [["О проекте федерального закона «О внесении изменений в Кодекс Российской Федерации об административных правонарушениях» (в части усиления административной ответственности за управление транспортным средством без прав)", "Законопроект подготовлен в целях повышения мер общественной безопасности в области дорожного движения и направлен на сохранение жизни и здоровья граждан, предупреждение общественно опасных действий, совершаемых лицами, не имеющими права управления транспортными средствами."], ["О проекте федерального закона «О внесении изменений в Федеральный закон “О связи”» (в части установления требований к соискателям (владельцам) лицензий на осуществление деятельности в области оказания услуг связи)", "Законопроект направлен на противодействие легализации (отмыванию) доходов, полученных преступным путем, и финансированию терроризма."]], '29.10.2026': [["О ходе подготовки предприятий жилищно-коммунального хозяйства и субъектов электроэнергетики к прохождению осенне-зимнего периода 2026–2027 годов", "Доклад Минстроя России."], ["О проекте федерального закона «О внесении изменения в статью 28.3 КоАП РФ»", "Меры против незаконной добычи драгоценных металлов и камней и незаконных финансовых операций с ними."], ["О внесении изменения в Положение о Минприроды России (постановление №1219)", "Полномочие утверждать методику определения вреда от негативного воздействия вод."], ["О проекте федерального закона «О внесении изменений в статью 52 Градостроительного кодекса РФ»", "Расширение перечня подготовительных работ до выдачи разрешения на строительство."], ["О внесении изменений в Положение о Россельхознадзоре (постановление №327)", "Приведение полномочий ведомства в соответствие с законодательством."], ["О выделении Минсельхозу России средств из резервного фонда Правительства на субсидии по льготным кредитам аграриям", "Финансирование федерального проекта «Экспорт продукции АПК»."], ["О проекте федерального закона «О внесении изменений в статью 15.47 КоАП РФ»", "Ответственность за нарушение порядка представления информации об операциях с драгметаллами и драгкамнями."], ["О проекте федерального закона «О внесении изменений в статью 51.2 Закона „О защите конкуренции“»", "Пересмотр решений по антимонопольным делам по новым или вновь открывшимся обстоятельствам."], ["О проекте федерального закона «О внесении изменений в КоАП РФ»", "Срок давности по антимонопольным нарушениям и нарушениям в сфере гособоронзаказа при пересмотре решений."], ["О проекте федерального закона «О внесении изменения в статью 20 Закона „О бесплатной юридической помощи в РФ“»", "Бесплатная юрпомощь лицам, к которым применяется исполнительная или постпенитенциарная пробация."], ["О внесении изменений в Положение о Минэнерго России (постановление №400)", "Приведение полномочий Минэнерго в соответствие с законодательством."]] };
