function calCks(): string[] { const n = new Date(); const st = new Set<string>([0, 1].map((k) => calCk(new Date(n.getFullYear(), n.getMonth() + k, 1)))); [...CAL.p.map((x: any) => x.d), ...CAL.g.map((x: any) => x[0]), ...CAL.w.flatMap((x: any) => [x[0], x[1]])].forEach((d: string) => { if (d) st.add(calCk(pd(d))); }); return [...st].sort((a, b) => (a.slice(3) + a.slice(0, 2)).localeCompare(b.slice(3) + b.slice(0, 2))); }
